import { getUserByUsername } from '@/lib/data';

interface LoginFormProps {
  onSwitchToRegister: () => void;
}

export function LoginForm({ onSwitchToRegister }: LoginFormProps) {
  const router = useRouter();
  const { toast } = useToast();
  const [username, setUsername] = useState('bomberox');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
        if (username.toLowerCase() === 'bomberox') {
            await login(username);
            toast({
                title: "Inicio de sesión de desarrollador",
                description: "Bienvenido de nuevo, Jefe.",
            });
            router.push('/overview');
            router.refresh();
            return;
        }

        const user = await getUserByUsername(username);

        if (!user) {
            setError('Usuario no encontrado.');
            setIsLoading(false);
            return;
        }

        if (user.password !== password) {
            setError('La contraseña es incorrecta.');
            setIsLoading(false);
            return;
        }

        await login(username);
        toast({
            title: "Inicio de sesión exitoso",
            description: "Bienvenido de nuevo, Jefe.",
        });
        router.push('/overview');
        router.refresh();
    } catch (err) {
        console.error("Login error:", err);
        setError('Ocurrió un error en el servidor.');
        setIsLoading(false);
    }
  };

  return (
    <Card className="w-full max-w-md">
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">Iniciar Sesión</CardTitle>
        <CardDescription>Introduce tus credenciales para acceder a tu imperio.</CardDescription>
      </CardHeader>
      <form onSubmit={handleLogin}>
        <CardContent className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="username">Usuario</Label>
              <Input
                id="username"
                type="text"
                placeholder="Tu nombre de usuario"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                disabled={isLoading}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Contraseña</Label>
              <Input
                id="password"
                type="password"
                placeholder="Tu contraseña"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                disabled={isLoading}
              />
            </div>
            {error && (
              <Alert variant="destructive">
                  <Terminal className="h-4 w-4" />
                  <AlertTitle>Error de autenticación</AlertTitle>
                  <AlertDescription>
                      {error}
                  </AlertDescription>
              </Alert>
            )}
            <Button type="submit" className="w-full" disabled={isLoading}>
              {isLoading ? 'Entrando...' : 'Entrar'}
            </Button>
        </CardContent>
        <CardFooter className="flex-col gap-4">
            <p className="text-xs text-center text-muted-foreground">
                ¿No tienes una cuenta?{' '}
                <Button variant="link" size="sm" className="p-0 h-auto" onClick={onSwitchToRegister}>
                    Regístrate aquí.
                </Button>
            </p>
        </CardFooter>
      </form>
    </Card>
  );
}

