// Inspired by react-hot-toast library
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

'use server';

import prisma from "../prisma/prisma";
import { login } from "../auth";
import { revalidatePath } from "next/cache";

interface RegisterUserInput {
    username: string;
    password: string;
    location: {
        ciudad: number;
        barrio: number;
        edificio: number;
    }
}

async function findAvailableSlot(): Promise<{ ciudad: number; barrio: number; edificio: number; }> {
    for (let c = 1; c <= 100; c++) {
        for (let b = 1; b <= 100; b++) {
            for (let e = 1; e <= 225; e++) {
                const existing = await prisma.propiedad.findUnique({
                    where: { ciudad_barrio_edificio: { ciudad: c, barrio: b, edificio: e } }
                });
                if (!existing) {
                    return { ciudad: c, barrio: b, edificio: e };
                }
            }
        }
    }
    return { ciudad: 1, barrio: 1, edificio: Math.floor(Math.random() * 225) + 1 };
}

export async function registerUser(input: RegisterUserInput) {
    const { username, password, location } = input;

    const existingUser = await prisma.user.findUnique({
        where: { username }
    });

    if (existingUser) {
        return { error: 'El nombre de usuario ya está en uso.' };
    }

    let finalLocation = location;
    const existingProperty = await prisma.propiedad.findUnique({
        where: { ciudad_barrio_edificio: { ciudad: location.ciudad, barrio: location.barrio, edificio: location.edificio } }
    });

    if (existingProperty) {
        finalLocation = await findAvailableSlot();
    }

    try {
        const allRoomConfigs = await prisma.configuracionHabitacion.findMany();

        const newUser = await prisma.user.create({
            data: {
                username,
                password,
                name: username,
                title: 'Nuevo Jefe',
                avatarUrl: `https://placehold.co/128x128.png`,
                propiedades: {
                    create: {
                        nombre: 'Propiedad Principal',
                        ciudad: finalLocation.ciudad,
                        barrio: finalLocation.barrio,
                        edificio: finalLocation.edificio,
                        armas: 10000,
                        municion: 10000,
                        alcohol: 10000,
                        dolares: 10000,
                        habitaciones: {
                            create: allRoomConfigs.map(config => ({
                                configuracionHabitacionId: config.id,
                                nivel: 1
                            }))
                        }
                    }
                },
                puntuacion: {
                    create: {
                        puntosHabitaciones: 0,
                        puntosTropas: 0,
                        puntosEntrenamientos: 0,
                        puntosTotales: 0,
                    }
                }
            }
        });

        await login(newUser.username);

        revalidatePath('/');
        return { success: true, user: newUser };

    } catch (error) {
        console.error('Error durante el registro:', error);
        return { error: 'Ocurrió un error en el servidor durante el registro.' };
    }
}

'use server'

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { getPropertyOwner, getTroopConfigurations } from "../data";
import { calcularDistancia, calcularDuracionViaje, calcularVelocidadFlota } from "../formulas/mission-formulas";

interface MissionInput {
    origenPropiedadId: string;
    coordinates: {
        ciudad: number;
        barrio: number;
        edificio: number;
    },
    tropas: { id: string, cantidad: number }[];
    tipo: string;
}

const MISIONES_SIN_RETORNO = ['OCUPAR'];

export async function enviarMision(input: MissionInput) {
    const user = await getSessionUser();
    if (!user) {
        return { error: "Usuario no autenticado." };
    }

    const { origenPropiedadId, coordinates, tropas, tipo } = input;
    const origenPropiedad = user.propiedades.find(p => p.id === origenPropiedadId);

    if (!origenPropiedad) {
        return { error: "Propiedad de origen no encontrada." };
    }

    if (!coordinates.ciudad || !coordinates.barrio || !coordinates.edificio) {
        return { error: "Coordenadas incompletas." };
    }
     if (tropas.length === 0 || tropas.every(t => t.cantidad === 0)) {
        return { error: "Debes seleccionar al menos una tropa." };
    }

    const tropasPropiedadMap = new Map(origenPropiedad.tropas.map(t => [t.configuracionTropaId, t.cantidad]));

    for (const tropa of tropas) {
        if ((tropasPropiedadMap.get(tropa.id) || 0) < tropa.cantidad) {
            return { error: `No tienes suficientes unidades de una de las tropas seleccionadas en ${origenPropiedad.nombre}.` };
        }
    }

    // Calcular distancia y duración
    const troopConfigs = await getTroopConfigurations();
    const troopConfigsMap = new Map(troopConfigs.map(t => [t.id, t]));

    const velocidadFlota = await calcularVelocidadFlota(tropas, troopConfigsMap);
    const distancia = await calcularDistancia(origenPropiedad, coordinates);
    const duracionViaje = await calcularDuracionViaje(distancia, velocidadFlota);

    const fechaInicio = new Date();
    const fechaLlegada = new Date(fechaInicio.getTime() + duracionViaje * 1000);
    const requiereRetorno = !MISIONES_SIN_RETORNO.includes(tipo);
    const fechaRegreso = requiereRetorno ? new Date(fechaLlegada.getTime() + duracionViaje * 1000) : null;


    if (tipo === 'OCUPAR') {
        const targetOwner = await getPropertyOwner(coordinates);
        if (targetOwner) {
            return { error: "No puedes ocupar una propiedad que ya tiene dueño." };
        }

        const tropaOcupacion = tropas.find(t => t.id === 'ocupacion');
        if (!tropaOcupacion || tropaOcupacion.cantidad === 0) {
            return { error: "Necesitas enviar al menos una Tropa de Ocupación para esta misión." };
        }

        try {
            await prisma.$transaction(async (tx) => {
                const allRoomConfigs = await tx.configuracionHabitacion.findMany();
                await tx.propiedad.create({
                    data: {
                        userId: user.id,
                        nombre: `Colonia en ${coordinates.ciudad}:${coordinates.barrio}`,
                        ciudad: coordinates.ciudad,
                        barrio: coordinates.barrio,
                        edificio: coordinates.edificio,
                        armas: 10000,
                        municion: 10000,
                        alcohol: 10000,
                        dolares: 10000,
                        habitaciones: {
                            create: allRoomConfigs.map(config => ({
                                configuracionHabitacionId: config.id,
                                nivel: 1
                            }))
                        }
                    }
                });

                await tx.tropaUsuario.update({
                    where: { propiedadId_configuracionTropaId: { propiedadId: origenPropiedadId, configuracionTropaId: 'ocupacion' } },
                    data: { cantidad: { decrement: tropaOcupacion.cantidad } }
                });
            });

            revalidatePath('/overview');
            revalidatePath('/map');
            return { success: `¡Has ocupado exitosamente la propiedad en ${coordinates.ciudad}:${coordinates.barrio}:${coordinates.edificio}!` };

        } catch (error) {
            console.error(error);
            return { error: "Error al crear la nueva propiedad." };
        }
    }

    try {
        await prisma.$transaction(async (tx) => {
            await tx.colaMisiones.create({
                data: {
                    userId: user.id,
                    propiedadOrigenId: origenPropiedadId,
                    tipoMision: tipo,
                    tropas: JSON.stringify(tropas),
                    origenCiudad: origenPropiedad.ciudad,
                    origenBarrio: origenPropiedad.barrio,
                    origenEdificio: origenPropiedad.edificio,
                    destinoCiudad: coordinates.ciudad,
                    destinoBarrio: coordinates.barrio,
                    destinoEdificio: coordinates.edificio,
                    fechaInicio: fechaInicio,
                    fechaLlegada: fechaLlegada,
                    fechaRegreso: fechaRegreso,
                    velocidadFlota,
                    duracionViaje,
                }
            });

            for (const t of tropas) {
                if (t.cantidad > 0) {
                    await tx.tropaUsuario.update({
                        where: { propiedadId_configuracionTropaId: { propiedadId: origenPropiedadId, configuracionTropaId: t.id } },
                        data: { cantidad: { decrement: t.cantidad } }
                    });
                }
            }
        });

    } catch (error) {
        console.error("Error al crear la misión:", error);
        return { error: "No se pudo enviar la misión." };
    }

    revalidatePath('/missions');
    revalidatePath('/overview');

    return { success: `Misión de ${tipo} enviada a ${coordinates.ciudad}:${coordinates.barrio}:${coordinates.edificio}.` };
}


export async function cancelarMision(misionId: string) {
    const user = await getSessionUser();
    if (!user) {
        return { error: "Usuario no autenticado." };
    }

    const mision = await prisma.colaMisiones.findUnique({
        where: { id: misionId }
    });

    if (!mision || mision.userId !== user.id) {
        return { error: "Misión no encontrada o no te pertenece." };
    }

    if (new Date() > new Date(mision.fechaLlegada)) {
        return { error: "No se puede cancelar una misión que ya ha llegado a su destino." };
    }

    const ahora = new Date();
    const tiempoTranscurrido = ahora.getTime() - new Date(mision.fechaInicio).getTime();
    const nuevaFechaRegreso = new Date(ahora.getTime() + tiempoTranscurrido);

    try {
        await prisma.colaMisiones.update({
            where: { id: misionId },
            data: {
                tipoMision: 'REGRESO',
                fechaRegreso: nuevaFechaRegreso,
            }
        });
        revalidatePath('/overview');
        revalidatePath('/missions');
        return { success: "La misión ha sido cancelada y la flota está de regreso." };

    } catch (error) {
        console.error("Error al cancelar la misión:", error);
        return { error: "No se pudo cancelar la misión." };
    }

}

'use server';

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { FullConfiguracionHabitacion } from "../data";
import { calcularCostosNivel, calcularTiempoConstruccion } from "../formulas/room-formulas";

export async function iniciarAmpliacion(propiedadId: string, habitacionId: string) {
    const user = await getSessionUser();

    if (!user) {
      return { error: 'Usuario no autenticado.' };
    }

    const propiedadActual = user.propiedades.find(p => p.id === propiedadId);
    if (!propiedadActual) {
        return { error: 'Propiedad no encontrada para este usuario.' };
    }

    const construccionesEnCola = propiedadActual.colaConstruccion;

    if (construccionesEnCola.length >= 5) {
        return { error: 'La cola de construcción está llena (máximo 5).' };
    }

    const habitacionUsuario = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === habitacionId);

    if (!habitacionUsuario) {
         return { error: 'Configuración de habitación de usuario no encontrada.' };
    }

    const config = habitacionUsuario.configuracion;
    if (!config) {
        return { error: 'Configuración de la habitación no encontrada.'}
    }

    const nivelBase = habitacionUsuario.nivel;
    const mejorasEnCola = construccionesEnCola.filter(c => c.habitacionId === habitacionId).length;
    const nivelSiguiente = nivelBase + mejorasEnCola + 1;

    const nivelOficinaJefe = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === 'oficina_del_jefe')?.nivel || 1;

    const costos = calcularCostosNivel(nivelSiguiente, config as FullConfiguracionHabitacion);

    if (
      propiedadActual.armas < costos.armas ||
      propiedadActual.municion < costos.municion ||
      propiedadActual.dolares < costos.dolares
    ) {
      return { error: 'No tienes suficientes recursos para esta ampliación.' };
    }

    const duracion = calcularTiempoConstruccion(nivelSiguiente, config, nivelOficinaJefe);

    try {
      await prisma.$transaction([
        prisma.propiedad.update({
          where: { id: propiedadId },
          data: {
            armas: { decrement: costos.armas },
            municion: { decrement: costos.municion },
            dolares: { decrement: costos.dolares },
          },
        }),
        prisma.colaConstruccion.create({
            data: {
                propiedadId: propiedadId,
                habitacionId: habitacionId,
                nivelDestino: nivelSiguiente,
                duracion: duracion,
                fechaInicio: null,
                fechaFinalizacion: null,
            }
        })
      ]);

      revalidatePath('/rooms');
      revalidatePath('/overview'); 
      revalidatePath('/(dashboard)/layout', 'layout');

      return { success: `¡${config.nombre} añadido a la cola de construcción!` };
    } catch (error) {
      console.error('Error durante la transacción de ampliación:', error);
      return { error: 'Ocurrió un error en el servidor al intentar ampliar.' };
    }
}

'use server';

import { getTrainingConfigurations, getTroopConfigurations } from '../data';
import { calcularStatsTropaConBonus } from '../formulas/troop-formulas';
import type { ConfiguracionTropa } from '@prisma/client';

interface TroopData {
    id: string;
    quantity: number;
}

interface TrainingData {
    id: string;
    level: number;
}

interface DefenseData {
    id: string;
    level: number;
}

export interface SimulationInput {
    troops: TroopData[];
    trainings: TrainingData[];
    defenses: DefenseData[];
    buildingsLevel: number;
}

export interface BattleReport {
    winner: 'attacker' | 'defender' | 'draw';
    rounds: BattleRoundReport[];
    finalStats: CombatStats;
    finalMessage: string;
}

export interface BattleRoundReport {
    round: number;
    attacker: RoundParticipantReport;
    defender: RoundParticipantReport;
}

export interface RoundParticipantReport {
    troops: {
        id: string;
        nombre: string;
        initialQuantity: number;
        lostQuantity: number;
    }[];
    totalAttack: number;
    totalDefense: number;
}

export interface CombatStats {
    attacker: {
        troopsLost: number;
        pointsLost: number;
        resourcesLost: ResourceCost;
    };
    defender: {
        troopsLost: number;
        pointsLost: number;
        resourcesLost: ResourceCost;
    };
}

interface ResourceCost {
    armas: number;
    municion: number;
    dolares: number;
}

interface ArmyUnit {
    id: string;
    nombre: string;
    config: ConfiguracionTropa;
    quantity: number;
    attack: number;
    defense: number;
}

function calculateResourceLoss(lostTroops: ArmyUnit[]): ResourceCost {
    return lostTroops.reduce((total, unit) => {
        total.armas += unit.config.costoArmas * unit.quantity;
        total.municion += unit.config.costoMunicion * unit.quantity;
        total.dolares += unit.config.costoDolares * unit.quantity;
        return total;
    }, { armas: 0, municion: 0, dolares: 0 });
}


export async function runBattleSimulation(attacker: SimulationInput, defender: SimulationInput): Promise<BattleReport> {
    const [troopConfigs, trainingConfigs] = await Promise.all([
        getTroopConfigurations(),
        getTrainingConfigurations()
    ]);
    const troopConfigsMap = new Map(troopConfigs.map(t => [t.id, t]));
    const trainingConfigsMap = new Map(trainingConfigs.map(t => [t.id, t]));

    const buildArmy = (simInput: SimulationInput): ArmyUnit[] => {
        const userTrainings = simInput.trainings.map(t => ({
            configuracionEntrenamientoId: t.id,
            nivel: t.level,
            configuracion: trainingConfigsMap.get(t.id)!
        }));

        return simInput.troops.map(troop => {
            const config = troopConfigsMap.get(troop.id);
            if (!config) return null;
            const { ataqueActual, defensaActual } = calcularStatsTropaConBonus(config, userTrainings as any);
            return {
                id: troop.id,
                nombre: config.nombre,
                config,
                quantity: troop.quantity,
                attack: ataqueActual,
                defense: defensaActual,
            };
        }).filter((u): u is ArmyUnit => u !== null && u.quantity > 0);
    };

    let attackerArmy = buildArmy(attacker);
    let defenderArmy = buildArmy(defender);

    const initialAttackerArmy = JSON.parse(JSON.stringify(attackerArmy));
    const initialDefenderArmy = JSON.parse(JSON.stringify(defenderArmy));

    const battleRounds: BattleRoundReport[] = [];
    let finalMessage = "";

    for (let i = 1; i <= 5; i++) {
        const attackerTroopCount = attackerArmy.reduce((sum, u) => sum + u.quantity, 0);
        const defenderTroopCount = defenderArmy.reduce((sum, u) => sum + u.quantity, 0);

        if (attackerTroopCount === 0 || defenderTroopCount === 0) {
            if(attackerTroopCount === 0) finalMessage = "Todas las tropas atacantes han sido destruidas.";
            if(defenderTroopCount === 0) finalMessage = "Todas las tropas defensoras han sido destruidas.";
            break;
        }

        const roundAttackerArmy = JSON.parse(JSON.stringify(attackerArmy));
        const roundDefenderArmy = JSON.parse(JSON.stringify(defenderArmy));

        const attackerTotalAttack = attackerArmy.reduce((sum, u) => sum + u.attack * u.quantity, 0);
        const defenderTotalAttack = defenderArmy.reduce((sum, u) => sum + u.attack * u.quantity, 0);

        const defenseBonus = defender.defenses.reduce((sum, d) => sum + (d.level * 0.05), 1) * (1 + (defender.buildingsLevel * 0.1));
        const attackerTotalDefense = attackerArmy.reduce((sum, u) => sum + u.defense * u.quantity, 0);
        const defenderTotalDefense = defenderArmy.reduce((sum, u) => sum + u.defense * u.quantity, 0) * defenseBonus;

        const attackerLossRate = defenderTotalAttack > attackerTotalDefense ? 1 : defenderTotalAttack / (attackerTotalDefense || 1);
        const defenderLossRate = attackerTotalAttack > defenderTotalDefense ? 1 : attackerTotalAttack / (defenderTotalDefense || 1);

        const attackerLossesThisRound = attackerArmy.map(u => ({ ...u, quantity: Math.floor(u.quantity * attackerLossRate) }));
        const defenderLossesThisRound = defenderArmy.map(u => ({ ...u, quantity: Math.floor(u.quantity * defenderLossRate) }));

        attackerArmy.forEach(u => u.quantity -= Math.floor(u.quantity * attackerLossRate));
        defenderArmy.forEach(u => u.quantity -= Math.floor(u.quantity * defenderLossRate));

        battleRounds.push({
            round: i,
            attacker: {
                troops: troopConfigs.map(config => {
                    const troop = roundAttackerArmy.find((t: ArmyUnit) => t.id === config.id);
                    const loss = attackerLossesThisRound.find(l => l.id === config.id);
                    return {
                        id: config.id,
                        nombre: config.nombre,
                        initialQuantity: troop?.quantity || 0,
                        lostQuantity: loss?.quantity || 0,
                    };
                }),
                totalAttack: attackerTotalAttack,
                totalDefense: attackerTotalDefense
            },
            defender: {
                 troops: troopConfigs.map(config => {
                    const troop = roundDefenderArmy.find((t: ArmyUnit) => t.id === config.id);
                    const loss = defenderLossesThisRound.find(l => l.id === config.id);
                    return {
                        id: config.id,
                        nombre: config.nombre,
                        initialQuantity: troop?.quantity || 0,
                        lostQuantity: loss?.quantity || 0,
                    };
                }),
                totalAttack: defenderTotalAttack,
                totalDefense: defenderTotalDefense,
            },
        });
    }

    const finalAttackerTroops = new Map(attackerArmy.map(u => [u.id, u.quantity]));
    const finalDefenderTroops = new Map(defenderArmy.map(u => [u.id, u.quantity]));

    const totalAttackerLossesArray: ArmyUnit[] = initialAttackerArmy.map((u: ArmyUnit) => ({ ...u, quantity: u.quantity - (finalAttackerTroops.get(u.id) || 0)}));
    const totalDefenderLossesArray: ArmyUnit[] = initialDefenderArmy.map((u: ArmyUnit) => ({...u, quantity: u.quantity - (finalDefenderTroops.get(u.id) || 0)}));

    const finalStats: CombatStats = {
        attacker: {
            troopsLost: totalAttackerLossesArray.reduce((s, u) => s + u.quantity, 0),
            pointsLost: totalAttackerLossesArray.reduce((s, u) => s + u.config.puntos * u.quantity, 0),
            resourcesLost: calculateResourceLoss(totalAttackerLossesArray)
        },
        defender: {
            troopsLost: totalDefenderLossesArray.reduce((s, u) => s + u.quantity, 0),
            pointsLost: totalDefenderLossesArray.reduce((s, u) => s + u.config.puntos * u.quantity, 0),
            resourcesLost: calculateResourceLoss(totalDefenderLossesArray)
        }
    }

    const attackerHasTroops = attackerArmy.some(u => u.quantity > 0);
    const defenderHasTroops = defenderArmy.some(u => u.quantity > 0);

    let winner: 'attacker' | 'defender' | 'draw' = 'draw';
    if(attackerHasTroops && !defenderHasTroops) winner = 'attacker';
    else if (!attackerHasTroops && defenderHasTroops) winner = 'defender';


    if (!finalMessage) {
        finalMessage = winner === 'attacker' ? "El atacante ha ganado la batalla." : winner === 'defender' ? "El defensor ha repelido el ataque." : "La batalla ha terminado en empate.";
    }

    return { winner, rounds: battleRounds, finalStats, finalMessage };
}

