import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { getTrainingConfigurations } from "../data";
import { calcularCostosEntrenamiento } from "../formulas/training-formulas";

export async function iniciarEntrenamiento(trainingId: string, propertyId: string) {
    const user = await getSessionUser();

    if (!user) {
      return { error: 'Usuario no autenticado.' };
    }

    const propiedadActual = user.propiedades.find(p => p.id === propertyId);
    if (!propiedadActual) {
        return { error: 'Propiedad no encontrada para este usuario.' };
    }

    const allTrainingConfigs = await getTrainingConfigurations();
    const config = allTrainingConfigs.find(c => c.id === trainingId);

    if (!config) {
        return { error: 'Configuración de entrenamiento no encontrada.'}
    }

    const userTraining = user.entrenamientos.find(t => t.configuracionEntrenamientoId === trainingId);

    const nivelActual = userTraining ? userTraining.nivel : 0;
    const nivelSiguiente = nivelActual + 1;

    const costos = calcularCostosEntrenamiento(nivelSiguiente, config);

    if (
      propiedadActual.armas < costos.armas ||
      propiedadActual.municion < costos.municion ||
      propiedadActual.dolares < costos.dolares
    ) {
      return { error: 'No tienes suficientes recursos en esta propiedad para el entrenamiento.' };
    }

    try {
      await prisma.$transaction(async (tx) => {
        await tx.propiedad.update({
          where: { id: propertyId },
          data: {
            armas: { decrement: costos.armas },
            municion: { decrement: costos.municion },
            dolares: { decrement: costos.dolares },
          },
        });

        if (userTraining) {
            await tx.entrenamientoUsuario.update({
                where: {
                    userId_configuracionEntrenamientoId: {
                        userId: user.id,
                        configuracionEntrenamientoId: trainingId,
                    }
                },
                data: {
                    nivel: { increment: 1 },
                }
            });
        } else {
             await tx.entrenamientoUsuario.create({
                data: {
                    userId: user.id,
                    configuracionEntrenamientoId: trainingId,
                    nivel: 1
                }
             })
        }
      });

      revalidatePath('/training');
      revalidatePath('/overview'); 

      return { success: `¡${config.nombre} mejorado a nivel ${nivelSiguiente}!` };
    } catch (error) {
      console.error('Error durante la transacción de entrenamiento:', error);
      return { error: 'Ocurrió un error en el servidor al intentar entrenar.' };
    }
  }

'use server';

import { revalidatePath } from "next/cache";
import prisma from "../prisma/prisma";
import { getSessionUser } from "../auth";
import { getTroopConfigurations } from "../data";
import { calcularTiempoReclutamiento } from "../formulas/troop-formulas";


export async function iniciarReclutamiento(propiedadId: string, tropaId: string, cantidad: number) {
    const user = await getSessionUser();

    if (!user) {
      return { error: 'Usuario no autenticado.' };
    }

    if (cantidad <= 0) {
        return { error: 'La cantidad debe ser mayor que cero.' };
    }

    const propiedadActual = user.propiedades.find(p => p.id === propiedadId);
    if (!propiedadActual) {
        return { error: 'Propiedad no encontrada para este usuario.' };
    }

    if (propiedadActual.colaReclutamiento) {
        return { error: 'Ya hay un reclutamiento en progreso en esta propiedad.' };
    }

    const troopConfigs = await getTroopConfigurations();
    const config = troopConfigs.find(t => t.id === tropaId);

    if (!config) {
         return { error: 'Configuración de tropa no encontrada.' };
    }

    const nivelCampoEntrenamiento = propiedadActual.habitaciones.find(h => h.configuracionHabitacionId === 'campo_de_entrenamiento')?.nivel || 1;

    const costoArmasTotal = config.costoArmas * cantidad;
    const costoMunicionTotal = config.costoMunicion * cantidad;
    const costoDolaresTotal = config.costoDolares * cantidad;

    const tiempoTotal = calcularTiempoReclutamiento(config, cantidad, nivelCampoEntrenamiento);

    if (
      propiedadActual.armas < costoArmasTotal ||
      propiedadActual.municion < costoMunicionTotal ||
      propiedadActual.dolares < costoDolaresTotal
    ) {
      return { error: 'No tienes suficientes recursos para este reclutamiento.' };
    }

    try {
      const fechaInicio = new Date();
      const fechaFinalizacion = new Date(fechaInicio.getTime() + tiempoTotal * 1000);

      await prisma.$transaction([
        prisma.propiedad.update({
          where: { id: propiedadId },
          data: {
            armas: { decrement: costoArmasTotal },
            municion: { decrement: costoMunicionTotal },
            dolares: { decrement: costoDolaresTotal },
          },
        }),
        prisma.colaReclutamiento.create({
            data: {
                propiedadId: propiedadId,
                tropaId: tropaId,
                cantidad: cantidad,
                fechaInicio: fechaInicio,
                fechaFinalizacion: fechaFinalizacion
            }
        })
      ]);

      revalidatePath('/recruitment');
      revalidatePath('/overview'); 
      revalidatePath('/(dashboard)/layout', 'layout');

      return { success: `¡El reclutamiento de ${cantidad} x ${config.nombre} ha comenzado!` };
    } catch (error) {
      console.error('Error durante la transacción de reclutamiento:', error);
      return { error: 'Ocurrió un error en el servidor al intentar reclutar.' };
    }
}

'use server';

import prisma from "../prisma/prisma";
import type { FullPropiedad, UserWithProgress } from "../data";
import { calculateStorageCapacity, calcularProduccionTotalPorSegundo } from "../formulas/room-formulas";
import { revalidatePath } from "next/cache";
import { calcularPuntosEntrenamientos, calcularPuntosHabitaciones, calcularPuntosTropas } from "../formulas/score-formulas";
import { getSessionUser } from "../auth";

interface UserSettings {
    name?: string;
    title?: string;
    avatarUrl?: string;
}

export async function updateUserSettings(settings: UserSettings) {
    const user = await getSessionUser();

    if (!user) {
        return { error: "Usuario no autenticado." };
    }

    try {
        await prisma.user.update({
            where: { id: user.id },
